import{_ as r,o as l,c as a,a3 as i,j as e,a as n}from"./chunks/framework.z_KJ15Ep.js";const s="/bilder/import-export-statistik/datenaustausch-erzeugbare-schnittstellendateien.png",d="/bilder/import-export-statistik/datenaustausch-schnittstellenbeispiel.png",k=JSON.parse('{"title":"Aufbau und Regeln der SchILD-NRW-Schnittstelle verstehen","description":"","frontmatter":{"title":"Aufbau und Regeln der SchILD-NRW-Schnittstelle verstehen","source_pageid":861,"source_revision":6953},"headers":[],"relativePath":"schild3/import-export-statistik/schnittstelle-schild-vorbemerkungen.md","filePath":"schild3/import-export-statistik/schnittstelle-schild-vorbemerkungen.md"}'),o={name:"schild3/import-export-statistik/schnittstelle-schild-vorbemerkungen.md"};function h(c,t,u,m,p,g){return l(),a("div",null,[...t[0]||(t[0]=[i('<h1 id="aufbau-und-regeln-der-schild-nrw-schnittstelle-verstehen" tabindex="-1">Aufbau und Regeln der SchILD-NRW-Schnittstelle verstehen <a class="header-anchor" href="#aufbau-und-regeln-der-schild-nrw-schnittstelle-verstehen" aria-label="Permalink to &quot;Aufbau und Regeln der SchILD-NRW-Schnittstelle verstehen&quot;">​</a></h1><p>Beachten Sie Dateiaufbau, Zeichencodierung, Datentypen und den Umgang mit leeren Feldern, bevor Sie Schnittstellendateien importieren.</p><p>Dieses Dokument beschreibt die Text-Importschnittstelle für <strong>SchILD-NRW 3</strong>.</p><h2 id="hinweise" tabindex="-1">Hinweise <a class="header-anchor" href="#hinweise" aria-label="Permalink to &quot;Hinweise&quot;">​</a></h2><p><a href="/bilder/import-export-statistik/datenaustausch-erzeugbare-schnittstellendateien.png"><img src="'+s+'" alt="Diese Schnittstellendateien können an einem Gymnasium im- und exportiert werden und enthalten die jeweiligen Daten. Je nach Schulform kann die Dateiliste abweichen." loading="lazy"></a></p><p><em>Diese Schnittstellendateien können an einem Gymnasium im- und exportiert werden und enthalten die jeweiligen Daten. Je nach Schulform kann die Dateiliste abweichen.</em></p><p><a href="/bilder/import-export-statistik/datenaustausch-schnittstellenbeispiel.png"><img src="'+d+'" alt="Einige Schnittstellendateien im Windows-Explorer." loading="lazy"></a></p><p><em>Einige Schnittstellendateien im Windows-Explorer.</em></p><p>Die Schnittstelle von SchILD-NRW 3 wurde ursprünglich für den Import bzw. Export statistikrelevanter Daten eingeführt. Mittlerweile lassen sich darüber die meisten (nicht alle!) Schüler- und Lehrerdaten importieren und exportieren.</p><p>Die Schnittstelle basiert auf einer Vielzahl von Textdateien mit der Endung <em>*.dat</em>. Diese enthalten Daten im CSV-Format, bei dem die Datenfelder durch ein „|“ (Pipe) als Trennzeichen getrennt sind.</p><p>Der Import erfolgt aus mehreren Textdateien, deren Struktur nachfolgend erläutert wird.</p>',11),e("div",{"data-hint-kind":"caution",class:"danger custom-block"},[e("p",{class:"custom-block-title"},[e("svg",{class:"hint-icon","data-icon":"caution","aria-hidden":"true",focusable:"false",viewBox:"0 0 24 24",fill:"none",stroke:"currentColor","stroke-width":"1.8","stroke-linecap":"round","stroke-linejoin":"round"},[e("path",{d:"m10.3 4-8 14A2 2 0 0 0 4 21h16a2 2 0 0 0 1.7-3l-8-14a2 2 0 0 0-3.4 0Z"}),e("path",{d:"M12 9v4m0 4v.1"})]),n("Achtung")]),e("p",null,[n("Konsultieren Sie für die konkreten Dateien, deren Inhalte und die korrekte Befüllung unbedingt die "),e("strong",null,"Schnittstellenbeschreibung"),n("!")])],-1),e("div",{"data-hint-kind":"info",class:"info custom-block"},[e("p",{class:"custom-block-title"},[e("svg",{class:"hint-icon","data-icon":"info","aria-hidden":"true",focusable:"false",viewBox:"0 0 24 24",fill:"none",stroke:"currentColor","stroke-width":"1.8","stroke-linecap":"round","stroke-linejoin":"round"},[e("circle",{cx:"12",cy:"12",r:"9"}),e("path",{d:"M12 11v6m0-10v.1"})]),n("Hinweis")]),e("p",null,[n("Die Textdateien können in den Codierungen "),e("em",null,"ANSI"),n(" oder "),e("em",null,"UTF-8"),n(" (Unicode) gespeichert werden – beide Formate werden unterstützt.")]),e("p",null,"Bitte achten Sie bei UTF-8-Dateien darauf, dass diese mit BOM (Byte Order Mark) gespeichert werden. Dies ist bei einigen Tabellenkalkulationsprogrammen (z. B. LibreOffice) nicht immer der Fall.")],-1),i(`<h2 id="beispiel" tabindex="-1">Beispiel <a class="header-anchor" href="#beispiel" aria-label="Permalink to &quot;Beispiel&quot;">​</a></h2><p>Die Datei <em>Klassen.dat</em> enthält beispielsweise die Daten zu den angelegten Klassen aus der <em>Klassen- und Versetzungstabelle</em>.</p><pre><code>InternBez|StatistikBez|SonstigeBez|Jahrgang|Folgeklasse|Klassenlehrer|OrgForm|Klassenart|Gliederung|Fachklasse|Jahr|Abschnitt
05A|05A|05A|05|06A|WEER|1|RK|***||2022|1
05B|05B|05B|05|06B|BOTS|1|RK|***||2022|1
05C|05C|05C|05|06C|JANS|1|RK|***||2022|1
05D|05D||05|06D|BAUE|1|RK|***||2022|1
06A|06A|06A|06|07A|GÜNT|1|RK|***||2022|1
06B|06B|06B|06|07B|WEID|1|RK|***||2022|1
</code></pre><h2 id="fur-alle-textdateien-gelten-folgende-bedingungen" tabindex="-1">Für alle Textdateien gelten folgende Bedingungen <a class="header-anchor" href="#fur-alle-textdateien-gelten-folgende-bedingungen" aria-label="Permalink to &quot;Für alle Textdateien gelten folgende Bedingungen&quot;">​</a></h2><ul><li>SchILD-NRW 3 erwartet, dass die Schnittstellendateien exakt die in der <strong>Schnittstellenbeschreibung</strong> angegebenen Dateinamen besitzen. Beispielsweise wird <em>Sbasis.dat</em> anstelle von <em>SchuelerBasisdaten.dat</em> nicht erkannt.</li><li>Jede Zeile muss genau einen Datensatz enthalten.</li><li>Als Trennzeichen zwischen den Feldern wird das Pipe-Symbol „|“ verwendet. Dies hat den Vorteil, dass z. B. in Bemerkungen auch ein Semikolon verwendet werden kann.</li><li>Textfelder werden nicht durch Anführungszeichen eingeschlossen.</li><li>Datumsfelder müssen im Format <em>TT.MM.JJJJ</em> vorliegen.</li><li>Die Spalten (Felder) müssen exakt in der vorgegebenen Reihenfolge erscheinen.</li><li>Jede Datei enthält eine <em>Header-Zeile</em> mit den Bezeichnungen der einzelnen Spalten. Diese dient nur zur Information und wird beim Import nicht ausgewertet.</li><li>Auch die Header-Zeile muss mit „|“ getrennt sein.</li><li>Bei leeren Feldern muss dennoch ein Trennzeichen „|“ ausgegeben werden, d. h. jede Zeile muss exakt die erwartete Anzahl an Trennzeichen enthalten.</li></ul><h2 id="umgang-mit-leeren-feldern" tabindex="-1">Umgang mit leeren Feldern <a class="header-anchor" href="#umgang-mit-leeren-feldern" aria-label="Permalink to &quot;Umgang mit leeren Feldern&quot;">​</a></h2><p>Bei den einzelnen Spalten ist angegeben, <strong>ob diese leer sein dürfen</strong>. Dabei treten folgende Zustände auf:</p><ul><li><em>Nein</em>: Spalte darf nicht leer sein, d. h. sie muss einen gültigen Wert enthalten.</li><li><em>(Ja)</em>: Spalte darf technisch leer sein, für die Statistik-Erhebung wird jedoch ggf. ein Eintrag in SchILD-NRW 3 benötigt. Dieser muss dann nach dem Import ergänzt werden.</li><li><em>Ja</em>: Spalte darf leer sein.</li></ul><h2 id="datentypen" tabindex="-1">Datentypen <a class="header-anchor" href="#datentypen" aria-label="Permalink to &quot;Datentypen&quot;">​</a></h2><p>Bei den einzelnen Spalten ist jeweils <strong>der erwartete Datentyp</strong> angegeben:</p><ul><li><em>Text(n)</em>: Text mit einer maximalen Länge von n Zeichen (z. B. Text(20))</li><li><em>Integer</em>: Ganzzahl (z. B. -753, 0, 42 oder 1066)</li><li><em>Float</em>: Gleitkommazahl. Es kann entweder ein Komma oder ein Punkt als Dezimaltrennzeichen verwendet werden (z. B. 1,141592 oder 2.997)</li></ul><h2 id="partielle-bzw-additive-importe" tabindex="-1">Partielle bzw. additive Importe <a class="header-anchor" href="#partielle-bzw-additive-importe" aria-label="Permalink to &quot;Partielle bzw. additive Importe&quot;">​</a></h2><p>Es ist nicht erforderlich, alle beschriebenen Dateien in einem Schritt zu importieren. Einzelne Dateien können auch nachträglich importiert werden.</p><p>Voraussetzung ist jedoch, dass „übergeordnete“ Daten, auf die verwiesen wird, bereits in der Datenbank von SchILD-NRW 3 vorhanden sind (z. B. durch einen vorherigen Import).</p><p>Wenn beispielsweise <em>Lernabschnitts- und Leistungsdaten</em> separat importiert werden sollen, müssen folgende Daten bereits existieren:</p><ul><li>Die Basisdaten der Schüler</li><li>Die Lehrkräfte (z. B. Klassen- oder Fachlehrer)</li><li>Die Fächer</li><li>Die Kurse</li><li>Die Jahrgänge und Klassen</li></ul>`,16),e("div",{"data-hint-kind":"info",class:"info custom-block"},[e("p",{class:"custom-block-title"},[e("svg",{class:"hint-icon","data-icon":"info","aria-hidden":"true",focusable:"false",viewBox:"0 0 24 24",fill:"none",stroke:"currentColor","stroke-width":"1.8","stroke-linecap":"round","stroke-linejoin":"round"},[e("circle",{cx:"12",cy:"12",r:"9"}),e("path",{d:"M12 11v6m0-10v.1"})]),n("Hinweis")]),e("p",null,"Falls übergeordnete Daten nicht vorhanden sind, wird der entsprechende Datensatz nicht importiert. Eine entsprechende Meldung erscheint im Importprotokoll.")],-1),e("p",null,"Schüler-Basisdaten und Schüler-Zusatzdaten können auch additiv importiert werden. Das bedeutet, dass fehlende Daten in einem späteren Import ergänzt werden können.",-1),e("div",{"data-hint-kind":"tip",class:"tip custom-block"},[e("p",{class:"custom-block-title"},[e("svg",{class:"hint-icon","data-icon":"tip","aria-hidden":"true",focusable:"false",viewBox:"0 0 24 24",fill:"none",stroke:"currentColor","stroke-width":"1.8","stroke-linecap":"round","stroke-linejoin":"round"},[e("path",{d:"M9 18h6m-5 3h4m-5-6c-4-3-4-9 0-11 5-3 11 1 9 6-.5 2-2 3-3 5v1H9z"})]),n("Tipp")]),e("p",null,"Falls bei einem Zweitimport Felder leer sind, die in SchILD-NRW 3 bereits gefüllt sind, bleiben die bestehenden Daten unverändert. So können Informationen gezielt ergänzt werden.")],-1),e("hr",null,null,-1),e("p",null,[e("a",{href:"https://schulverwaltungsinfos.nrw.de/svws/wiki/index.php?title=Schnittstelle_SchILD_-_Vorbemerkungen",target:"_blank",rel:"noreferrer"},"Originalartikel im Wiki"),n(" · Quellrevision 6953.")],-1)])])}const f=r(o,[["render",h]]);export{k as __pageData,f as default};
